function oddEvenJumps(arr) {
  const n = arr.length;

  function nextJump(order) {
    const next = new Array(n).fill(-1);
    const stack = [];
    for (const index of order) {
      while (stack.length > 0 && stack[stack.length - 1] < index) {
        next[stack.pop()] = index;
      }
      stack.push(index);
    }
    return next;
  }

  const indices = Array.from({ length: n }, (_, i) => i);
  const oddNext = nextJump([...indices].sort((a, b) => arr[a] - arr[b] || a - b));
  const evenNext = nextJump([...indices].sort((a, b) => arr[b] - arr[a] || a - b));

  const fromOdd = new Array(n).fill(false);
  const fromEven = new Array(n).fill(false);
  fromOdd[n - 1] = true;
  fromEven[n - 1] = true;
  let good = 1;

  for (let i = n - 2; i >= 0; i--) {
    if (oddNext[i] !== -1) {
      fromOdd[i] = fromEven[oddNext[i]];
    }
    if (evenNext[i] !== -1) {
      fromEven[i] = fromOdd[evenNext[i]];
    }
    if (fromOdd[i]) {
      good++;
    }
  }
  return good;
}

