function oddEvenJumps(arr) {
  // Walk from every start, scanning to the right for each jump's target.
  const n = arr.length;
  let count = 0;
  for (let start = 0; start < n; start++) {
    let at = start;
    let jump = 1;
    while (at !== n - 1) {
      let target = -1;
      for (let j = at + 1; j < n; j++) {
        if (jump % 2 === 1) {
          if (arr[j] >= arr[at] && (target === -1 || arr[j] < arr[target])) target = j;
        } else {
          if (arr[j] <= arr[at] && (target === -1 || arr[j] > arr[target])) target = j;
        }
      }
      if (target === -1) break;
      at = target;
      jump++;
    }
    if (at === n - 1) count++;
  }
  return count;
}

